sysml:
// in Funktionen
action <'F-008'> rampenBefahren {
    doc /* Das Fahrzeug fährt Rampen mit voller Last befahren. */
}

// in Anforderungen
requirement <'R-008'> maximaleFahrgeschwindigkeitPersonenverkehr {
    doc /* Das FTF fährt in Bereichen mit Personenverkehr höchstens 0,8 m/s. */
}

// in Verknuepfungen
satisfy Anforderungen::maximaleFahrgeschwindigkeitPersonenverkehr by Physik::ftf.fahrwerk;

// in Anforderungen
requirement <'R-008'> fahrzeugbreite {
    doc /* Das FTF hat eine Breite von höchstens 900 mm. */
}

// in Verknuepfungen
satisfy Anforderungen::fahrzeugbreite by Physik::ftf.sicherheitssteuerung;

// in Anforderungen
requirement <'R-008'> ladestandUnter15Prozent {
    doc /* Das FTF nimmt keine neuen Fahraufträge an, wenn der Akkuladestand unter 15 % liegt. */
}

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Das FTF fährt selbstständig zur Ladestation, wenn der Akkuladestand unter 15 % liegt. */
}

// in Verknuepfungen
satisfy Anforderungen::ladestandUnter15Prozent by Physik::ftf.akku;

// in Funktionen
action <'F-008'> zustandsMelden {
    doc /* Das FTF meldet Position, Ladestand und Störungen an das Leitsystem. */
}

// in Physik::ftf
part <'P-009'> zustandsMeldung : Logik::Funkmodul;

// in Anforderungen
requirement <'R-008'> verbindungsverlustAnhalten {
    doc /* Das FTF hält bei Verbindungsverlust von mehr als 5 Sekunden kontrolliert an. */
}

// in Funktionen
action <'F-008'> verbindungsverlustDetektieren {
    doc /* Verbindungsverlust überwachen und bei mehr als 5 Sekunden Halt auslösen. */
}

// in Verknuepfungen
satisfy Anforderungen::verbindungsverlustAnhalten by Physik::ftf.sicherheitssteuerung;

// in Anforderungen
requirement <'R-008'> lastaufnahmehoehe {
    doc /* Die Lastaufnahme hebt Ladungsträger um bis zu 120 mm an. */
}

// in Verknuepfungen
satisfy Anforderungen::lastaufnahmehoehe by Physik::ftf.hubwerk;

// in Funktionen
action <'F-008'> lastHandhabenGitterboxenEuropaletten {
    doc /* Ladungsträger Gitterboxen und Europaletten aufnehmen und abgeben. */
}

// in Physik::ftf
part <'P-009'> lastHandhaber : Logik::Lastaufnahme;

// in Verknuepfungen
allocate Funktionen::lastHandhabenGitterboxenEuropaletten to Physik::ftf.lastHandhaber;

// in Anforderungen
requirement <'R-008'> zweischichtbetrieb {
    doc /* Das FTF arbeitet im Zweischichtbetrieb mit 30 Minuten Ladepause zwischen den Schichten. */
}

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Das Fahrzeug selbstständig zur Ladestation fahren und dort kontaktlos laden. */
}

// in Physik::ftf
part <'P-009'> ladestationAnfahren : Logik::Fahrwerk;

// in Verknuepfungen
satisfy Anforderungen::zweischichtbetrieb by Physik::ftf.sicherheitssteuerung;

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Das Fahrzeug fährt selbstständig zur Ladestation, wenn der Akkuladestand unter 15 % liegt. */
}

// in Logik
part def <'L-009'> LadestationSensor {
    doc /* Sensoreinrichtung, die den Akkuladestand überwacht. */
}

// in Physik::ftf
part <'P-009'> ladestationSensor : Logik::LadestationSensor;

// in Funktionen
action <'F-008'> akustischeUndOptischeWarnung {
    doc /* Akustische und optische Warnsignale bei Anfahren und Richtungswechseln auslösen. */
}

// in Logik
part def <'L-009'> AkustischerWarnsensor {
    doc /* Sensor für akustische Warnsignale. */
}
part def <'L-010'> OptischerWarnsensor {
    doc /* Sensor für optische Warnsignale. */
}

// in Physik::ftf
part <'P-009'> akustischerWarnsensor : Logik::AkustischerWarnsensor;
part <'P-010'> optischerWarnsensor : Logik::AkustischerWarnsensor;

// in Funktionen
action <'F-008'> stoerungMelden {
    doc /* Das FTF meldet Störungen an das Leitsystem. */
}

// in Funktionen
action <'F-008'> rueckwaertsUeberwachen {
    doc /* Rückwärsüberwachung des Schutzfeldes und Halt bei Hindernissen. */
}

// in Logik
part def <'L-009'> SicherheitslaserscannerRueckwaerts {
    doc /* Sensor, der Schutzfelder hinter dem Fahrzeug überwacht. */
}

// in Physik::ftf
part <'P-009'> scannerRueckwaerts : Logik::SicherheitslaserscannerRueckwaerts;

// in Funktionen
action <'F-008'> optischeWarnung {
    doc /* Optische Warnung durch die Warnleuchte. */
}

// in Logik
part def <'L-009'> Warnleuchte {
    doc /* Leuchte zur optischen Warnung. */
}

// in Physik::ftf
part <'P-009'> warnleuchte : Logik::Warnleuchte;

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Das FTF fährt zur Ladestation und beginnt das Kontaktlose Laden. */
}

// in Logik
part def <'L-009'> Ladespule {
    doc /* Elektromagnetische Spule für kontaktloses Laden. */
}

// in Physik::ftf
part <'P-009'> ladespule : Logik::Ladespule;

// in Funktionen
action <'F-008'> notHaltAusloesenRechts {
    doc /* Bei Betätigung des Not-Halt-Tasters auf der rechten Seite alle Antriebe sicher abschalten. */
}

// in Logik
part def <'L-009'> NotHaltTasterRechts {
    doc /* Not-Halt-Taster auf der rechten Fahrzeugseite. */
}

// in Physik::ftf
part <'P-009'> notHaltTasterRechts : Logik::NotHaltTasterRechts;

// in Funktionen
action <'F-008'> hindernisseErkennenHinten {
    doc /* Hindernisse und Personen im Schutzfeld hinter dem Fahrzeug erkennen. */
}

// in Physik::ftf
part <'P-009'> scannerHinten : Logik::Sicherheitslaserscanner;

// in Funktionen
action <'F-008'> sensorEinsetzen {
    doc /* Neuen Sensor in das Fahrzeug einbauen und anpassen. */
}

// in Logik
part def <'L-009'> Sensor {
    doc /* Unspezifischer Sensor für verschiedene Anwendungen. */
}

// in Physik::ftf
part <'P-009'> neuerSensor : Logik::Sensor;

// in Funktionen
action <'F-008'> akkulaufzeitBesserung {
    doc /* Verbessern der Akkulaufzeit. */
}

// in Logik
part def <'L-009'> Effizienzsteigerung {
    doc /* Steigerung der Effizienz des Energiespeichers. */
}

// in Physik::ftf
part <'P-009'> akkuleistungsoptimierung : Logik::Effizienzsteigerung;

// in Anforderungen
requirement <'R-008'> tragekapazitaet {
    doc /* Das FTF kann eine Last von bis zu 2000 kg tragen. */
}

// in Physik::ftf
part <'P-009'> lasttragwerk : Logik::Lastaufnahme;

// in Anforderungen
requirement <'R-008'> maximaleFahrgeschwindigkeitAutomatikbetrieb {
    doc /* Die Höchstgeschwindigkeit im Automatikbetrieb beträgt 3 m/s. */
}

// in Verknuepfungen
satisfy Anforderungen::maximaleFahrgeschwindigkeitAutomatikbetrieb by Physik::ftf.fahrwerk;
